INSERT INTO `settings` VALUES (1,'default_notification_option','only_assigned',NULL),(2,'text_formatting','common_mark',NULL),(3,'wiki_tablesort_enabled','0',NULL),(4,'default_projects_tracker_ids','---\n- \'1\'\n- \'2\'\n- \'3\'\n','2026-04-03 11:42:23'),(5,'attachment_max_size','102400','2026-04-03 13:33:11'),(6,'bulk_download_max_size','1024000','2026-04-04 04:28:13'),(7,'attachment_extensions_allowed','','2026-04-03 11:49:27'),(8,'attachment_extensions_denied','','2026-04-03 11:49:27'),(9,'file_max_size_displayed','5120','2026-04-04 04:28:26'),(10,'diff_max_lines_displayed','1500','2026-04-03 11:49:27'),(11,'repositories_encodings','','2026-04-03 11:49:27'),(12,'app_title','Sumago Infotech PVT LTD','2026-04-03 12:39:12'),(13,'welcome_text','**Welcome to Sumago Infotech Pvt Ltd**\r\n\r\nWe are glad to have you onboard. This platform serves as your central workspace for managing daily tasks, collaboration, and project tracking. Please follow the guidelines below to ensure smooth workflow and productivity.\r\n\r\n---\r\n\r\n**General Guidelines**\r\n\r\n1. **Start Your Day with Dashboard**\r\n   Always begin by reviewing your assigned tasks, updates, and priorities.\r\n\r\n2. **Maintain Data Security**\r\n   Use strong passwords, do not share credentials, and follow company security policies.\r\n\r\n3. **Communicate Clearly**\r\n   Inform your team about progress, raise blockers early, and stay aligned.\r\n\r\n4. **Continuous Learning**\r\n   Refer to documentation, training materials, and improve your skills regularly.\r\n\r\n---\r\n\r\n**Today\'s Focus**\r\n\r\n* Check assigned tasks and deadlines\r\n* Review announcements and updates\r\n* Attend scheduled meetings\r\n* Resolve blockers and dependencies\r\n\r\n---\r\n\r\n**Quick Access**\r\n\r\nTesting Sheet Link \r\n\r\nhttps://docs.google.com/spreadsheets/d/1l5Kw5nhwA-Vxc9BQmvYm42ssa_gBXVqRMr5o20ItLQ4/edit?gid=0#gid=0 \r\n\r\n---\r\n\r\n**Note**\r\n\r\nThis workspace is designed to improve collaboration, transparency, and efficiency across all teams at Sumago Infotech Pvt Ltd.\r\n\r\n---\r\n\r\n**© 2026 Sumago Infotech Pvt Ltd — Internal Use Only**','2026-04-04 09:39:26'),(14,'per_page_options','25,50,100','2026-04-03 12:39:12'),(15,'search_results_per_page','10','2026-04-03 12:39:12'),(16,'activity_days_default','10','2026-04-03 12:39:12'),(17,'host_name','localhost:3000','2026-04-03 12:39:12'),(18,'protocol','http','2026-04-03 12:39:12'),(19,'cache_formatted_text','0','2026-04-03 12:39:12'),(20,'wiki_compression','','2026-04-03 12:39:12'),(21,'feeds_limit','15','2026-04-03 12:39:12'),(22,'reactions_enabled','1','2026-04-03 12:39:12'),(23,'login_required','1','2026-04-03 12:48:55'),(24,'autologin','0','2026-04-03 12:48:33'),(25,'self_registration','0','2026-04-03 12:48:33'),(26,'show_custom_fields_on_registration','0','2026-04-03 12:48:33'),(27,'password_min_length','12','2026-04-03 12:51:03'),(28,'password_required_char_classes','---\n- uppercase\n- lowercase\n- digits\n- special_chars\n','2026-04-03 12:51:03'),(29,'password_max_age','60','2026-06-08 11:31:49'),(30,'lost_password','0','2026-04-03 12:51:03'),(31,'twofa','0','2026-04-03 12:51:03'),(32,'session_lifetime','1440','2026-06-08 11:31:49'),(33,'session_timeout','0','2026-04-03 12:48:33'),(34,'rest_api_enabled','0','2026-04-03 13:27:53'),(35,'jsonp_enabled','0','2026-04-03 13:27:53'),(36,'webhooks_enabled','1','2026-04-03 13:27:53'),(37,'cross_project_issue_relations','0','2026-04-04 08:34:52'),(38,'link_copied_issue','ask','2026-04-04 08:34:52'),(39,'copy_attachments_on_issue_copy','ask','2026-04-04 08:34:52'),(40,'cross_project_subtasks','tree','2026-04-04 08:34:52'),(41,'close_duplicate_issues','1','2026-04-04 08:34:52'),(42,'issue_group_assignment','0','2026-04-04 08:34:52'),(43,'default_issue_start_date_to_creation_date','1','2026-04-04 08:34:52'),(44,'display_subprojects_issues','1','2026-04-04 08:34:52'),(45,'issue_done_ratio','issue_field','2026-04-04 08:34:52'),(46,'issue_done_ratio_interval','10','2026-